```javascript
import {
  Group,
  Mesh,
  BoxGeometry,
  PlaneGeometry,
  Shape,
  ExtrudeGeometry,
  Vector3,
  Color,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  uniform,
  uv,
  vec3,
  mix,
  smoothstep,
  color,
  positionLocal,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { textContent } = config;
  const items = textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Map label to navigation target
  const navMap = {
    HOME: 'hub-home',
    FEATURES: 'hub-features',
    COLLECTION: 'hub-collection',
    PRICING: 'hub-pricing',
    JOURNAL: 'hub-journal',
  };

  // Main group
  const group = new Group();

  // --- Rail (chamfered box) ---
  const shape = new Shape();
  const w = 3.6;
  const h = 0.5;
  const r = 0.1;
  shape.moveTo(-w / 2 + r, -h / 2);
  shape.lineTo(w / 2 - r, -h / 2);
  shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
  shape.lineTo(w / 2, h / 2 - r);
  shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
  shape.lineTo(-w / 2 + r, h / 2);
  shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
  shape.lineTo(-w / 2, -h / 2 + r);
  shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);

  const extrudeSettings = {
    depth: 0.05,
    bevelEnabled: true,
    bevelSize: 0.02,
    bevelSegments: 3,
  };
  const railGeo = new ExtrudeGeometry(shape, extrudeSettings);
  // Rotate to lay flat
  railGeo.rotateX(-Math.PI / 2);

  // Rail material with vertical gradient and metal properties
  const railMat = new MeshStandardNodeMaterial();
  // Gradient using uv - we need to map uv.y from 0 to 1 across the face
  // The extrude geometry has uv, but we can use local position to get y
  const yPos = positionLocal.y;
  const topColor = color('#1b1b23');
  const bottomColor = color('#101015');
  const t = smoothstep(0.0, 0.5, yPos); // y from -0.25 to 0.25 -> map to 0-1
  const mixed = mix(bottomColor, topColor, t);
  railMat.colorNode = mixed;
  railMat.roughness = 0.55;
  railMat.metalness = 0.5;
  railMat.clearcoat = 0.2;
  railMat.anisotropy = 0.6;
  railMat.anisotropyRotation = 0; // along x

  const rail = new Mesh(railGeo, railMat);
  rail.position.z = 0.15; // floating height
  group.add(rail);

  // --- Contact shadow ---
  const shadowGeo = new PlaneGeometry(3.8, 0.7);
  const shadowMat = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.35,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.z = 0.15 - 0.06; // offset down
  group.add(shadow);

  // --- Text entries ---
  const entries = [];
  const entryPositions = [];

  // Precompute centers
  const spacing = 0.68;
  const startX = -2 * spacing;
  for (let i = 0; i < 5; i++) {
    entryPositions[i] = startX + i * spacing;
  }

  // Underline bar
  const underlineGeo = new BoxGeometry(0.28, 0.025, 0.01);
  const underlineMat = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.8,
  });
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.z = 0.16;
  group.add(underline);

  let activeIndex = 0; // HOME is active initially

  // Create each text item
  const textGroups = [];
  items.forEach((item, index) => {
    const label = item.text.toUpperCase();
    const isActive = index === activeIndex;

    // Create text using font atlas
    const textOpts = {
      fontSize: 0.13,
      color: isActive ? '#e8ecf2' : '#a6adba',
      align: 'center',
      letterSpacing: 0.08,
    };
    const textObj = ctx.fontAtlas.createText(label, textOpts);
    textObj.position.z = 0.16; // on top of rail

    // Hit area mesh (invisible, for click/hover)
    const hitGeo = new PlaneGeometry(0.6, 0.34);
    const hitMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0,
      depthWrite: false,
    });
    const hitMesh = new Mesh(hitGeo, hitMat);
    hitMesh.position.z = 0.16;

    // Group for this entry
    const entryGroup = new Group();
    entryGroup.add(textObj);
    entryGroup.add(hitMesh);
    entryGroup.position.set(entryPositions[index], 0, 0);
    entryGroup.userData = { index, label };

    group.add(entryGroup);
    textGroups.push(entryGroup);
    entries.push({ group: entryGroup, textObj, isActive, label });
  });

  // Position underline under active entry
  function updateUnderline(index) {
    const targetX = entryPositions[index];
    // Animate with GSAP
    gsap.to(underline.position, {
      x: targetX,
      duration: 0.26,
      ease: 'power4.out',
      onUpdate: () => {
        // overshoot simulation: not needed as GSAP handles ease
      },
    });
  }
  updateUnderline(activeIndex);

  // Update text colors on active change
  function setActive(index) {
    const prev = activeIndex;
    activeIndex = index;
    // Update underline
    updateUnderline(index);
    // Update text colors
    entries.forEach((entry, i) => {
      const color = i === index ? '#e8ecf2' : '#a6adba';
      // Since we can't change individual text object color easily, we need to recreate? 
      // But ctx.fontAtlas.createText returns a group with material?
      // We'll assume we can change the material color of the text object.
      // The text object likely has a material property. We'll traverse to find a mesh.
      // For simplicity, we'll destroy and recreate the text object? That's heavy.
      // Better: we can store the text mesh and update its material color.
      // We'll assume the text object is a mesh with a material.
      const textObj = entry.textObj;
      if (textObj.isMesh) {
        textObj.material.color.set(color);
      } else {
        // Traverse children to find a mesh
        textObj.traverse((child) => {
          if (child.isMesh) {
            child.material.color.set(color);
          }
        });
      }
    });
  }

  // --- Event handlers ---
  group.userData.handlers = {
    click: (event) => {
      // Determine which entry was clicked
      // We'll use raycasting from the event details? The event object may have intersection info.
      // For simplicity, we'll attach click handlers to each hitMesh.
    },
    hover: (event) => {
      // Inactive entries change color on hover
    },
  };

  // Since we need per-entry click/hover, we'll attach directly to the hitMesh.
  // We'll store a cleanup function for each entry.
  const cleanupFns = [];

  entries.forEach((entry, index) => {
    const hitMesh = entry.group.children[1]; // second child is hitMesh
    const textObj = entry.textObj;

    // Hover in
    const hoverIn = () => {
      if (index !== activeIndex) {
        // Change text color to paper
        if (textObj.isMesh) {
          gsap.to(textObj.material.color, { r: 232/255, g: 236/255, b: 242/255, duration: 0.16, ease: 'power2.out' });
        } else {
          textObj.traverse((child) => {
            if (child.isMesh) {
              gsap.to(child.material.color, { r: 232/255, g: 236/255, b: 242/255, duration: 0.16, ease: 'power2.out' });
            }
          });
        }
      }
    };
    const hoverOut = () => {
      if (index !== activeIndex) {
        // Revert to inactive color
        if (textObj.isMesh) {
          gsap.to(textObj.material.color, { r: 166/255, g: 173/255, b: 186/255, duration: 0.16, ease: 'power2.out' });
        } else {
          textObj.traverse((child) => {
            if (child.isMesh) {
              gsap.to(child.material.color, { r: 166/255, g: 173/255, b: 186/255, duration: 0.16, ease: 'power2.out' });
            }
          });
        }
      }
    };

    // Press animation
    const press = () => {
      const tl = gsap.timeline();
      tl.to(entry.group.position, { z: 0.16 - 0.03, duration: 0.12, ease: 'back.out(1.275)' })
        .to(entry.group.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(1.275)' }, 0);
      // After press, if active change, we might reset scale
      // We'll handle that in the click action
      return tl;
    };

    // Click handler
    const onClick = () => {
      if (index === activeIndex) return; // already active
      // Press animation then switch active
      const tl = gsap.timeline();
      tl.add(press());
      tl.call(() => {
        setActive(index);
        // Emit navigation
        const target = navMap[entry.label];
        if (target) ctx.emit('navigate', { to: target });
        // Reset scale of this entry (the underline will move)
        gsap.to(entry.group.scale, { x: 1, y: 1, duration: 0.2, ease: 'power2.out' });
        gsap.to(entry.group.position, { z: 0.16, duration: 0.2, ease: 'power2.out' });
      });
    };

    // Attach handlers to hitMesh
    hitMesh.addEventListener('pointerover', hoverIn);
    hitMesh.addEventListener('pointerout', hoverOut);
    hitMesh.addEventListener('pointerdown', onClick);

    // Store cleanup for this entry
    cleanupFns.push(() => {
      hitMesh.removeEventListener('pointerover', hoverIn);
      hitMesh.removeEventListener('pointerout', hoverOut);
      hitMesh.removeEventListener('pointerdown', onClick);
    });
  });

  // --- Mount animation (rise-in) ---
  const mountTL = gsap.timeline();
  group.position.y = -0.4; // start below
  mountTL.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });

  // --- Cleanup ---
  group.userData.cleanup = () => {
    mountTL.kill();
    // Kill all GSAP tweens on group and its children
    gsap.killTweensOf(group);
    cleanupFns.forEach(fn => fn());
    // Dispose geometries and materials
    railGeo.dispose();
    railMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
    // Dispose text geometries? They are managed by font atlas, we assume it's handled elsewhere.
    // But we can't dispose them here without knowing internals.
    // We'll rely on the font atlas to handle cleanup.
  };

  return group;
}
